<script setup>
import {ref,watch} from 'vue'
import {memberRpc} from './member-service.js'
const props=defineProps({users:{type:Array,default:()=>[]},currentCodes:{type:Array,default:()=>[]}}),emit=defineEmits(['updated'])
const action=ref(''),reason=ref(''),codes=ref(['seedling']),catalog=ref([]),busy=ref(false),message=ref(''),confirm=ref(false),request=ref('')
const labels={grade:'등급 변경',suspend:'활동 정지',resume:'활동 재개',withdraw:'강제 탈퇴'}
watch(()=>props.users.map(x=>x.id+':'+x.services_revision).join(','),()=>{action.value='';message.value=''})
async function begin(value){if(!props.users.length)return;action.value=value;reason.value='';confirm.value=false;message.value='';request.value=crypto.randomUUID();try{catalog.value=await memberRpc('member_service_catalog');const current=props.currentCodes.length?props.currentCodes:props.users.length===1?(await memberRpc('member_detail',{p_user:props.users[0].id})).services:[];codes.value=current.length?current.filter(c=>catalog.value.some(x=>x.id===c)):['seedling']}catch(e){message.value=e.message}}
function toggle(item,checked){if(checked){if(item.id==='seedling'){codes.value=['seedling'];return}codes.value=codes.value.filter(c=>c!=='seedling');if(['base','ai','msp','pm'].includes(item.kind))codes.value=codes.value.filter(c=>!catalog.value.some(x=>x.id===c&&x.kind===item.kind));codes.value=[...codes.value,item.id]}else {codes.value=codes.value.filter(c=>c!==item.id);if(!codes.value.length)codes.value=['seedling']}}
async function save(){if(busy.value||!confirm.value||(action.value!=='grade'&&!reason.value.trim()))return;busy.value=true;try{await memberRpc('member_admin_bulk',{p_request:request.value,p_users:props.users.map(x=>x.id),p_action:action.value,p_reason:reason.value,p_codes:codes.value,p_versions:Object.fromEntries(props.users.map(x=>[x.id,x.services_revision??0]))});message.value=props.users.length+'명의 '+labels[action.value]+'을 기록했습니다.';action.value='';emit('updated')}catch(e){message.value=e.message}finally{busy.value=false}}
</script>
<template><section class="member-bulk-controls" aria-label="선택 회원 관리"><div class="member-actions"><strong>선택 {{users.length}}명</strong><button v-for="(label,key) in labels" :key="key" :disabled="busy||!users.length||users.some(u=>u.system_admin)" @click="begin(key)">{{label}}</button></div><p v-if="message" role="status">{{message}}</p><div v-if="action" class="member-action-backdrop" @keydown.esc="!busy&&(action='')"><section class="member-action-dialog" role="dialog" aria-modal="true" :aria-label="labels[action]+' 확인'"><h2>{{labels[action]}} · {{users.length}}명</h2><p class="member-targets">{{users.map(u=>u.display_name||u.email).join(', ')}}</p><template v-if="action==='grade'"><h3>변경 등급 선택 · 서비스 종류</h3><p>선택한 서비스 구성으로 변경합니다. 여러 분야를 선택할 수 있고 같은 분야는 한 등급만 적용합니다. 기존 프레스티지는 해당 분야를 새로 지정하지 않으면 보존합니다. 파트너는 시스템 관리자 권한을 부여하지 않습니다.</p><div class="service-code-options"><label v-for="item in catalog" :key="item.id"><input type="checkbox" :checked="codes.includes(item.id)" :disabled="busy" @change="toggle(item,$event.target.checked)">{{item.name}}</label></div></template><p v-else-if="action==='suspend'">관리자가 활동을 재개할 때까지 사이트의 보호 서비스 이용을 중지합니다. 회원정보와 이력은 보존합니다.</p><p v-else-if="action==='withdraw'">회원정보와 이력을 보존하고 사이트 이용 및 기존 그룹·프로젝트 접근을 회수합니다. 회원 데이터는 영구 삭제하지 않습니다.</p><p v-else>활동 정지를 해제합니다. 탈퇴 회원은 재개할 수 없습니다.</p><label>변경 사유{{action==='grade'?' (선택)':''}}<textarea v-model="reason" maxlength="2000" rows="3" :required="action!=='grade'"></textarea></label><label class="member-check"><input v-model="confirm" type="checkbox">선택한 회원과 변경 내용을 확인했습니다.</label><div class="member-actions"><button :disabled="busy||!confirm||(action!=='grade'&&!reason.trim())" @click="save">{{busy?'처리 중':'확인·적용'}}</button><button :disabled="busy" @click="action=''">취소</button></div></section></div></section></template>
<style scoped>.member-bulk-controls{border:1px solid #d7e2ef;background:#f4f8fe;padding:14px 18px;border-radius:10px;margin:18px 0}.member-action-backdrop{position:fixed;inset:0;z-index:210;background:#10223c66;display:grid;place-items:center;padding:20px}.member-action-dialog{background:white;color:#16334f;width:min(600px,100%);max-height:90vh;overflow:auto;border-radius:16px;padding:28px;box-shadow:0 18px 70px #10223c55}.member-action-dialog h2{font-size:24px;font-weight:750}.member-action-dialog h3{font-size:18px;font-weight:700;margin:20px 0 10px}.member-action-dialog p{line-height:1.7;margin:14px 0}.member-action-dialog label{display:grid;gap:8px;margin:14px 0}.member-action-dialog .member-check{display:flex;align-items:center}.member-action-dialog textarea{border:1px solid #b5c5d5;border-radius:6px;padding:12px;width:100%}.service-code-options{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.service-code-options label{display:flex;align-items:center;gap:10px;font-size:14px}.service-code-options input,.member-check input{width:19px;height:19px}.member-targets{overflow-wrap:anywhere}.member-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.member-actions button{border:1px solid #a9bfd6;border-radius:6px;padding:9px 12px;background:white;font-weight:650}.member-actions button:disabled{opacity:.45}@media(max-width:480px){.service-code-options{grid-template-columns:1fr}.member-action-dialog{padding:20px}}</style>
